import "server-only";
import { db } from "@/lib/db";
import { cancelQueuedIn } from "@/lib/cancellation";
import { AppError } from "@/lib/errors";
import { ensureDeletionJob, runDeletionJob } from "@/lib/deletion-jobs";
export { DELETION_DRAIN_MS, DELETION_RETENTION_MS } from "@/lib/deletion-jobs";

export async function requestAccountDeletion(userId: string, email: string) {
  const result = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const user = await tx.user.findUnique({ where: { id: userId } });
    if (!user || email !== user.email)
      throw new AppError("Type your account email exactly to confirm.");
    await tx.user.update({
      where: { id: userId },
      data: {
        deletionRequestedAt: user.deletionRequestedAt ?? new Date(),
        gmailAuthorized: false,
        billingStateVersion: { increment: 1 },
      },
    });
    await ensureDeletionJob(tx, userId);
    // Only the job needs the deadline-limited revocation credential now.
    await tx.user.update({
      where: { id: userId },
      data: { encryptedRefreshToken: null },
    });
    return cancelQueuedIn(tx, userId);
  });
  await runDeletionJob(userId, new Date(), { billingOnly: true }).catch(
    () => false,
  );
  return result;
}
export async function cleanupDeletedAccount(userId: string, now = new Date()) {
  return runDeletionJob(userId, now);
}

export async function exportAccount(userId: string) {
  const profile = await db.user.findFirst({
    where: { id: userId, deletionRequestedAt: null },
    select: {
      id: true,
      email: true,
      name: true,
      createdAt: true,
      preferredRoles: true,
      followUpDays: true,
      gmailAuthorized: true,
      gmailScopes: true,
      gmailSendOnlyConsentAt: true,
      currentAttachmentId: true,
    },
  });
  if (!profile) throw new AppError("Account unavailable.");
  const [contacts, templates, campaigns, attachments, deliveryReceipts] =
    await Promise.all([
      db.contact.findMany({
        where: { userId },
        select: {
          id: true,
          name: true,
          email: true,
          company: true,
          jobRole: true,
          notes: true,
          tag: true,
          archivedAt: true,
          followUpRequestedAt: true,
          shortlistRemovedAt: true,
          createdAt: true,
        },
      }),
      db.template.findMany({
        where: { userId },
        select: {
          id: true,
          name: true,
          subject: true,
          body: true,
          archivedAt: true,
          createdAt: true,
        },
      }),
      db.campaign.findMany({
        where: { userId, sends: { some: { historyDeletedAt: null } } },
        select: {
          id: true,
          templateId: true,
          status: true,
          role: true,
          attachmentId: true,
          createdAt: true,
          sends: {
            where: { campaign: { userId }, historyDeletedAt: null },
            select: {
              id: true,
              contactId: true,
              recipientEmail: true,
              recipientName: true,
              recipientRole: true,
              recipientCompany: true,
              templateName: true,
              subject: true,
              body: true,
              status: true,
              deliveryState: true,
              createdAt: true,
              sentAt: true,
              cancelledAt: true,
              attemptedAt: true,
              replyMarkedAt: true,
              bouncedAt: true,
              sentConfirmedManuallyAt: true,
              gmailMessageId: true,
              gmailThreadId: true,
              error: true,
            },
          },
        },
      }),
      db.attachment.findMany({
        where: { userId },
        select: { id: true, fileName: true, createdAt: true, deletedAt: true },
      }),
      db.deliveryReceipt.findMany({
        where: { userId },
        select: {
          id: true,
          recipientEmail: true,
          createdAt: true,
          sentAt: true,
        },
      }),
    ]);
  const [subscriptions, usage] = await Promise.all([
    db.billingSubscription.findMany({
      where: { userId },
      select: {
        status: true,
        periodStart: true,
        periodEnd: true,
        gracePeriodEnd: true,
        cancelAtPeriodEnd: true,
        currency: true,
        recurringAmountMinor: true,
        paymentConfirmedAt: true,
      },
    }),
    db.usagePeriod.findMany({
      where: { userId },
      select: {
        kind: true,
        startsAt: true,
        endsAt: true,
        operationalEndsAt: true,
        sent: true,
        reserved: true,
      },
    }),
  ]);
  return {
    version: 2,
    subscriptions,
    usage,
    exportedAt: new Date().toISOString(),
    profile,
    contacts,
    templates,
    campaigns,
    attachments,
    deliveryReceipts,
  };
}
